args.query:
SELECT COUNT(*) AS n
FROM information_schema.columns
WHERE table_name='fct_subscriptions' AND column_name LIKE '%reason%';

SELECT column_name
FROM (SELECT * FROM sqlite_master WHERE type='table') AS t
LIMIT 1;

SELECT activity__active_date::date AS day,
       SUM(value_moments) AS value_moments,
       SUM(app_opens) AS app_opens
FROM (
  SELECT activity__active_date::date, value AS value_moments, NULL::INTEGER AS app_opens FROM (
    SELECT activity__active_date, value FROM (
      VALUES
      ('2026-07-06'::date,501),('2026-07-07',601),('2026-07-08',507),('2026-07-09',478),('2026-07-10',512),('2026-07-11',497),('2026-07-12',546)
    ) t(activity__active_date,value)
  ) v
  UNION ALL
  SELECT activity__active_date::date, NULL::INTEGER AS value_moments, value AS app_opens FROM (
    SELECT activity__active_date, value FROM (
      VALUES
      ('2026-07-06'::date,815),('2026-07-07',1032),('2026-07-08',854),('2026-07-09',826),('2026-07-10',876),('2026-07-11',804),('2026-07-12',863)
    ) t(activity__active_date,value)
  ) a
) s
GROUP BY day
ORDER BY day;

SELECT SUM(value_moments) AS total_value_moments, SUM(app_opens) AS total_app_opens FROM (
  VALUES
  (501,815),(601,1032),(507,854),(478,826),(512,876),(497,804),(546,863)
) t(value_moments, app_opens);
